package dev.starworld.runtime;

import dev.starworld.civic.*;
import dev.starworld.civic.CivicNeedsState.*;
import dev.starworld.domain.WorldState.*;
import dev.starworld.integration.CoreBridge;
import java.util.*;
import java.util.concurrent.CompletableFuture;
import java.util.function.Function;
import java.util.function.Consumer;
import org.bukkit.Server;
import org.bukkit.entity.Player;
import org.bukkit.plugin.java.JavaPlugin;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

class CivicNeedsControllerTest {
    private static final class Fixture {
        final JavaPlugin plugin=mock(JavaPlugin.class);final Server server=mock(Server.class);final WorldRuntime runtime=mock(WorldRuntime.class);final CoreBridge core=mock(CoreBridge.class);final CivicNeedsService service=mock(CivicNeedsService.class);final Player player=mock(Player.class);final UUID actor=UUID.randomUUID(),anchor=UUID.randomUUID();final CoreCity city=new CoreCity(UUID.randomUUID(),UUID.randomUUID(),"城","国",1,"fixture");final CityView view=new CityView(city.cityId(),city.nationId(),"城","agrarian",9,Map.of(),List.of(),null,"");final CivicNeedsController controller;
        Fixture(){this(type->Optional.empty());}
        Fixture(Function<String,Optional<String>> unavailable){when(plugin.getServer()).thenReturn(server);when(server.isPrimaryThread()).thenReturn(true);when(player.getUniqueId()).thenReturn(actor);when(player.isOnline()).thenReturn(true);when(player.hasPermission("starworld.use")).thenReturn(true);when(runtime.playerCity(player)).thenReturn(Optional.of(city));when(core.city(city.cityId())).thenReturn(Optional.of(city));when(runtime.city(city.cityId())).thenReturn(CompletableFuture.completedFuture(Optional.of(view)));when(runtime.currentPeriod()).thenReturn(10L);when(runtime.manage(player,city.cityId())).thenReturn(true);when(runtime.verifiedBuildings(view)).thenReturn(Set.of(anchor));controller=new CivicNeedsController(plugin,runtime,core,service,unavailable);}
        @SuppressWarnings("unchecked") void immediate(){when(runtime.async(any())).thenAnswer(c->{try{return CompletableFuture.completedFuture(((WorldRuntime.Work<?>)c.getArgument(0)).run());}catch(Exception e){return CompletableFuture.failedFuture(e);}});doAnswer(c->{((Consumer<Object>)c.getArgument(2)).accept(((CompletableFuture<?>)c.getArgument(1)).join());return null;}).when(runtime).reply(any(),any(),any());}
        Request request(UUID id,long period){return request(id,period,"community_meals");} Request request(UUID id,long period,String type){var need=CivicNeedsDefinitions.defaults().needs().get(type);return new Request(id,city.cityId(),city.nationId(),need,period,period+need.lifetimePeriods(),period/need.cooldownPeriods(),actor.toString(),Status.OPEN,-1);}
    }
    @Test void captureRejectsNonMainOfflineAndForeignNationWithoutUsingInventedEvidence(){Fixture f=new Fixture();assertEquals(Set.of(f.anchor),f.controller.capture(f.player,f.city,f.view).verified());when(f.server.isPrimaryThread()).thenReturn(false);assertThrows(IllegalStateException.class,()->f.controller.capture(f.player,f.city,f.view));when(f.server.isPrimaryThread()).thenReturn(true);when(f.player.isOnline()).thenReturn(false);assertThrows(IllegalArgumentException.class,()->f.controller.capture(f.player,f.city,f.view));when(f.player.isOnline()).thenReturn(true);when(f.core.city(f.city.cityId())).thenReturn(Optional.of(new CoreCity(f.city.cityId(),UUID.randomUUID(),"城","新国",1,"changed")));assertThrows(IllegalArgumentException.class,()->f.controller.capture(f.player,f.city,f.view));verify(f.runtime,times(1)).verifiedBuildings(any());}
    @Test void newRequestUsesCurrentPeriodWhileRetriedUuidUsesItsOriginalPeriod()throws Exception{Fixture f=new Fixture();f.immediate();UUID id=UUID.randomUUID();Request original=f.request(id,7);when(f.service.request(id)).thenReturn(Optional.of(original));when(f.service.request(id,f.city,"community_meals",7,f.actor.toString())).thenReturn(original);List<Request> results=new ArrayList<>();f.controller.requestFromPreview(f.player,f.city,"community_meals",id,results::add);verify(f.service).request(id,f.city,"community_meals",7,f.actor.toString());assertEquals(List.of(original),results);UUID fresh=UUID.randomUUID();Request created=f.request(fresh,10);when(f.service.request(fresh)).thenReturn(Optional.empty());when(f.service.request(fresh,f.city,"community_meals",10,f.actor.toString())).thenReturn(created);f.controller.requestFromPreview(f.player,f.city,"community_meals",fresh,r->{});verify(f.service).request(fresh,f.city,"community_meals",10,f.actor.toString());verify(f.runtime,never()).open(any());}
    @Test void revokedManagerAfterReadCannotRequestOrRecognizeAnyLifeAction()throws Exception{Fixture f=new Fixture();f.immediate();when(f.service.request(any(UUID.class))).thenReturn(Optional.empty());when(f.runtime.manage(f.player,f.city.cityId())).thenReturn(true,false);assertThrows(IllegalArgumentException.class,()->f.controller.requestFromPreview(f.player,f.city,"community_meals",UUID.randomUUID(),r->fail()));verify(f.service,never()).request(any(),any(),anyString(),anyLong(),anyString());verify(f.service,never()).complete(any(),any(),anyLong(),anyString());verify(f.runtime,never()).open(any());}
    @Test void nationChangeAfterReadCannotCompletePreviousNationNeed()throws Exception{Fixture f=new Fixture();f.immediate();when(f.core.city(f.city.cityId())).thenReturn(Optional.of(new CoreCity(f.city.cityId(),UUID.randomUUID(),"城","新国",1,"changed")));assertThrows(IllegalArgumentException.class,()->f.controller.completeFromPreview(f.player,f.city,UUID.randomUUID(),r->fail()));verify(f.service,never()).complete(any(),any(),anyLong(),anyString());verify(f.runtime,never()).verifiedBuildings(any());}
    @Test void missingFurnitureCapabilityBlocksNewAllocationButPreservesAValidRequestRetry() throws Exception {Fixture f=new Fixture(type->type.equals("public_spaces")?Optional.of("CraftEngine furniture API unavailable"):Optional.empty());f.immediate();UUID fresh=UUID.randomUUID();when(f.service.request(fresh)).thenReturn(Optional.empty());List<Request> results=new ArrayList<>();f.controller.requestFromPreview(f.player,f.city,"public_spaces",fresh,results::add);verify(f.service,never()).request(eq(fresh),eq(f.city),eq("public_spaces"),anyLong(),eq(f.actor.toString()));assertTrue(results.isEmpty());verify(f.player).sendMessage(contains("CraftEngine furniture API unavailable"));UUID existing=UUID.randomUUID();Request saved=f.request(existing,7,"public_spaces");when(f.service.request(existing)).thenReturn(Optional.of(saved));when(f.service.request(existing,f.city,"public_spaces",7,f.actor.toString())).thenReturn(saved);f.controller.requestFromPreview(f.player,f.city,"public_spaces",existing,results::add);verify(f.service).request(existing,f.city,"public_spaces",7,f.actor.toString());assertEquals(List.of(saved),results);}
    @Test void missingCurrentCapabilityDoesNotBlockCompletionOfAnExistingReceipt() throws Exception {Fixture f=new Fixture(type->Optional.of("CraftEngine 家具 API 不可用"));f.immediate();UUID id=UUID.randomUUID(),action=UUID.randomUUID();Receipt receipt=new Receipt(id,f.city.cityId(),f.city.nationId(),10,List.of(action),Map.of("minecraft:oak_planks",16L),1,1,true);when(f.service.complete(id,f.city,10,f.actor.toString())).thenReturn(receipt);List<Receipt> results=new ArrayList<>();f.controller.completeFromPreview(f.player,f.city,id,results::add);verify(f.service).complete(id,f.city,10,f.actor.toString());assertEquals(List.of(receipt),results);}
    @Test void civicOptionsExposeTheLiveCapabilityReason(){Fixture f=new Fixture(type->type.equals("public_spaces")?Optional.of("CraftEngine furniture API unavailable"):Optional.empty());when(f.service.definitions()).thenReturn(CivicNeedsDefinitions.defaults());assertTrue(f.controller.execute(f.player,new String[]{"civic","options"}));verify(f.player).sendMessage(contains("public_spaces"));verify(f.player).sendMessage(contains("暂不可用：CraftEngine"));}
    @Test void completeReturnsOnlyTheServicesActualReceiptWithItsClaimedActionIds()throws Exception{Fixture f=new Fixture();f.immediate();UUID id=UUID.randomUUID(),action=UUID.randomUUID();Receipt receipt=new Receipt(id,f.city.cityId(),f.city.nationId(),10,List.of(action),Map.of("minecraft:wheat",16L),1,1,true);when(f.service.complete(id,f.city,10,f.actor.toString())).thenReturn(receipt);List<Receipt> results=new ArrayList<>();f.controller.completeFromPreview(f.player,f.city,id,results::add);assertEquals(List.of(receipt),results);assertEquals(List.of(action),results.getFirst().claimedActionUUIDs());verify(f.service).complete(id,f.city,10,f.actor.toString());verify(f.runtime,never()).open(any());}
    @Test void statusAndHistoryHonorSmallerConfiguredPagination()throws Exception{Fixture f=new Fixture();f.immediate();var defaults=CivicNeedsDefinitions.defaults();when(f.service.definitions()).thenReturn(new CivicNeedsDefinitions(1,1,3,defaults.needs()));when(f.service.requests(f.city.cityId(),1,1)).thenReturn(List.of());when(f.service.history(f.city.cityId(),1,2)).thenReturn(List.of());f.controller.execute(f.player,new String[]{"civic","status","2"});f.controller.execute(f.player,new String[]{"civic","history","3"});verify(f.service).requests(f.city.cityId(),1,1);verify(f.service).history(f.city.cityId(),1,2);f.controller.execute(f.player,new String[]{"civic","history","5"});verify(f.service,never()).history(f.city.cityId(),1,4);}
}
